style.css:
css


body {

    background-color: #f0f0f0;

}

p, h1, h2, h3, h4, h5, h6 {

    color: #333;

    font-family: 'Arial', sans-serif;

}


a {

    color: #0077cc;

    text-decoration: none;

}


a:hover {

    text-decoration: underline;

}


button {

    background-color: #0077cc;

    color: white;

    border: none;

    border-radius: 5px;

    padding: 10px 15px;

    cursor: pointer;

}



button:hover {

    background-color: #005fa3;

}
